/**
 * One `UNICODED_FONTS` row: the font class, and its key -> text pairs.
 *
 * `hash_values` (`constants_rules.rb:122`) branches on the inner hash's
 * size, and the branch is visible in the tree: a one-entry font
 * contributes a bare `str(text)` with no tag, a many-entry font an
 * alternation of `str(font).absent?.as(font).as(:unicoded_font_class) >>
 * str(text).as(:symbol)`. Measured per font before emission, not read off
 * the source.
 */
export type UnicodemathUnicodedFont = readonly [
  fontClass: string,
  entries: ReadonlyArray<readonly [key: string, text: string]>,
];

/**
 * `Constants::UNICODED_FONTS` — `unicoded_fonts`
 * (`constants_rules.rb:41`), built by `unicoded_fonts_to_expression`
 * rather than by `arr_to_expression`, which is why it keeps its nesting.
 */
export const UNICODEMATH_UNICODED_FONTS: readonly UnicodemathUnicodedFont[] = [
  ["script", [["H", "&#x210b;"]]],
  ["fraktur", [["H", "&#x210c;"]]],
  ["double", [["H", "&#x210d;"]]],
  [
    "mitBbb",
    [
      ["D", "&#x2145;"],
      ["d", "&#x2146;"],
      ["e", "&#x2147;"],
      ["i", "&#x2148;"],
      ["j", "&#x2149;"],
    ],
  ],
];

/**
 * The tables that carry a text more than once, as
 * [table, entries, distinct, unreachable repeats].
 *
 * Emitted so the array-not-Map decision above carries its own evidence:
 * `test/formats/unicodemath/parser-tables.spec.ts` asserts each named
 * table still has exactly this many entries, so a future change to a
 * keyed shape fails loudly instead of shortening a grammar alternation.
 */
export const UNICODEMATH_REPEATED_TEXT_TABLES: ReadonlyArray<
  readonly [table: string, entries: number, distinct: number, repeats: number]
> = [
  ["UNICODEMATH_OPEN_SYMBOLS", 10, 8, 2],
  ["UNICODEMATH_CLOSE_SYMBOLS", 10, 8, 2],
  ["UNICODEMATH_ACCENT_SYMBOLS", 21, 18, 3],
  ["UNICODEMATH_SKIP_SYMBOLS", 9, 8, 1],
  ["UNICODEMATH_NARY_SYMBOLS", 25, 23, 2],
  ["UNICODEMATH_UNARY_SYMBOLS", 13, 11, 2],
  ["UNICODEMATH_BINARY_SYMBOLS", 47, 46, 1],
  ["UNICODEMATH_ORDINARY_SYMBOLS", 96, 91, 5],
  ["UNICODEMATH_RELATIONAL_SYMBOLS", 195, 185, 10],
];

/**
 * Decimal marker -> the text `decimal_marker`
 * (`unicode_math/parse.rb:294`) actually matches.
 *
 * The gem does not match the marker: it matches
 * `Utility.string_to_html_entity(marker)`, because `UnicodeMath::Parser`
 * entity-encodes its input before Parslet sees it. `.` and `,` encode to
 * themselves; `ar`/`fa`'s U+066B encodes to seven characters.
 *
 * Additive, not exclusive: `op_decimal` (`unicode_math/parse.rb:60`) is
 * `decimal_marker | str(",") | str(".")`, so a comma and a full stop
 * are decimal markers under every locale and the configured marker is a
 * third alternative. Asserted on every run.
 */
export const UNICODEMATH_ENCODED_DECIMAL_MARKERS: ReadonlyMap<string, string> = new Map([
  [",", ","],
  [".", "."],
  ["٫", "&#x66b;"],
]);
